mapper.update:
UPDATE t_balance_applied_fact
SET apply_status = #{status}, fact_type = #{fact.factType}, supersedes_fact_id = #{fact.supersedesFactId},
    superseded_by_fact_id = #{fact.supersededByFactId}, lines_hash = #{fact.linesHash},
    applied_time = #{fact.appliedTime}, update_time = #{now}
WHERE id = #{fact.id} AND apply_status = #{fact.applyStatus}

mapper.delete:
DELETE e FROM t_balance_applied_entry e
JOIN t_balance_applied_fact f ON f.id = e.applied_fact_id
WHERE f.entity_no = #{bookEntityId} AND f.currency = #{currency} AND f.fact_id <= #{factId}
